package com.drivique.api.payments;
import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
import com.drivique.api.dto.CashPaymentConfirmationRequestDTO; import com.drivique.api.model.*; import com.drivique.api.repository.*; import com.drivique.api.service.*; import java.math.BigDecimal; import java.time.Instant; import java.util.Optional; import org.junit.jupiter.api.Test;
class CashPaymentServiceTests {
 @Test void confirmsCashPaymentAndReservation() { ReservationRepository reservations=mock(ReservationRepository.class); RentalContractRepository contracts=mock(RentalContractRepository.class); PaymentRepository payments=mock(PaymentRepository.class); PaymentMethodRepository methods=mock(PaymentMethodRepository.class); PaymentStatusRepository paymentStatuses=mock(PaymentStatusRepository.class); ReservationStatusRepository reservationStatuses=mock(ReservationStatusRepository.class); CurrencyRepository currencies=mock(CurrencyRepository.class); UserRepository users=mock(UserRepository.class); PaymentReceiptService receipts=mock(PaymentReceiptService.class); CashPaymentService service=new CashPaymentService(reservations,contracts,payments,methods,paymentStatuses,reservationStatuses,currencies,users,receipts); Reservation reservation=mock(Reservation.class); Branch branch=mock(Branch.class); RentalContract contract=mock(RentalContract.class); PaymentMethod method=mock(PaymentMethod.class); PaymentStatus approved=mock(PaymentStatus.class); Currency currency=mock(Currency.class); User cashier=mock(User.class); ReservationStatus confirmed=mock(ReservationStatus.class); when(reservations.findByCashPaymentCodeIgnoreCase("CASH-123")).thenReturn(Optional.of(reservation)); when(reservation.getCashPaymentBranch()).thenReturn(branch); when(branch.allowsCashPayment()).thenReturn(true); when(reservation.getCashPaymentExpiresAt()).thenReturn(Instant.now().plusSeconds(3600)); when(contracts.findByReservationId(any())).thenReturn(Optional.of(contract)); when(payments.existsByGatewayProviderAndGatewayReference("EFECTIVO_CAJA","CASH-123")).thenReturn(false); when(users.findByEmailIgnoreCaseAndDeletedAtIsNull("cashier@drivique.com")).thenReturn(Optional.of(cashier)); when(methods.findByCodeIgnoreCaseAndActiveTrue("CASH")).thenReturn(Optional.of(method)); when(paymentStatuses.findByCodeIgnoreCase("APPROVED")).thenReturn(Optional.of(approved)); when(currencies.findByCodeIgnoreCaseAndActiveTrue("COP")).thenReturn(Optional.of(currency)); when(contract.getBaseAmount()).thenReturn(new BigDecimal("100000.00")); when(contract.getSecurityDeposit()).thenReturn(new BigDecimal("20000.00")); when(payments.saveAndFlush(any(Payment.class))).thenAnswer(i->i.getArgument(0)); when(reservationStatuses.findByCodeIgnoreCase("CONFIRMED")).thenReturn(Optional.of(confirmed)); service.confirm(new CashPaymentConfirmationRequestDTO("CASH-123"),"cashier@drivique.com"); verify(payments).saveAndFlush(any(Payment.class)); verify(receipts).generateFor(any(Payment.class)); verify(reservation).setStatus(confirmed); }
}
